/// An anonymous shared-memory file of `size` bytes (cwayland's helper).
pub fn create_shm(size: usize) -> Option<OwnedFd> {
    let fd = unsafe { aw_create_shm(size) };
    (fd >= 0).then(|| unsafe { OwnedFd::from_raw_fd(fd) })
}

