pub mod wl_registry {
    use super::*;
    pub fn interface() -> Interface { Interface(unsafe { &wl_registry_interface }) }
    /// The scanner's own destructor: libwayland forgets the proxy.
    pub fn destroy(o: Obj) {
        unsafe { wlc_wl_registry_destroy(o.raw()) };
        forget(o)
    }
    #[derive(Debug)]
    pub enum Event {
        Global { name: u32, interface: String, version: u32 },
        GlobalRemove { name: u32 },
    }
    unsafe fn decode(opcode: u32, a: *const Arg) -> Option<Event> {
        Some(match opcode {
            0 => { let a = unsafe { std::slice::from_raw_parts(a, 3) }; unsafe { Event::Global { name: a[0].u, interface: string(a[1].s), version: a[2].u } } }
            1 => { let a = unsafe { std::slice::from_raw_parts(a, 1) }; unsafe { Event::GlobalRemove { name: a[0].u } } }
            _ => return None,
        })
    }
    /// Every event of `o`, to `f`, until a destructor forgets it.
    pub fn listen(o: Obj, f: impl Fn(Event) + 'static) {
        listen_raw(o, Rc::new(move |op, a| if let Some(e) = unsafe { decode(op, a) } { f(e) }))
    }
}
